<script setup lang="ts">
import { confirmAction } from "../../confirmation";
import DownloadLink from "../../Components/DownloadLink.vue";
import{ref,computed}from'vue';import{Link,useForm,usePage}from'@inertiajs/vue3';import MainLayout from'../../Layouts/MainLayout.vue';const p=defineProps<{items:any[];activeClass:any}>(),page=usePage(),edit=ref<any>(null),f=useForm({nis:'',nama:'',kontak:''});const search=ref('');const filtered=computed(()=>p.items.filter(x=>(x.nis+' '+x.nama).toLowerCase().includes(search.value.toLowerCase())));const reset=()=>{edit.value=null;f.reset()};const load=(x:any)=>{edit.value=x;f.nis=x.nis;f.nama=x.nama;f.kontak=x.kontak??''};const save=()=>edit.value?f.patch(`/master/siswa/${edit.value.id}`,{onSuccess:reset}):f.post('/master/siswa',{onSuccess:reset});const remove=async(id:number)=>{if(await confirmAction('Siswa yang belum memiliki transaksi ini akan dihapus dari daftar.'))useForm({}).delete(`/master/siswa/${id}`)};const rp=(v:any)=>Number(v??0).toLocaleString('id-ID');
const upload = useForm({file:null as File|null});
const fileInput=ref<HTMLInputElement|null>(null);
function importStudents(){upload.post('/master/siswa/import',{forceFormData:true,preserveScroll:true,onSuccess:()=>{upload.reset();if(fileInput.value)fileInput.value.value='';}});}
</script>
<template><MainLayout><main class="p-4 sm:p-6 lg:p-8"><div class="mx-auto max-w-7xl"><div v-if="page.props.flash?.success" class="mb-4 rounded-lg bg-emerald-50 p-3 text-sm text-emerald-700">{{page.props.flash.success}}</div><div v-if="page.props.flash?.error" class="mb-4 rounded-lg bg-rose-50 p-3 text-sm text-rose-700">{{page.props.flash.error}}</div><div class="mb-6"><p class="text-sm font-bold uppercase tracking-widest text-indigo-600">Master data</p><h1 class="mt-2 text-2xl font-bold">Siswa</h1><p class="mt-1 text-sm text-slate-500">Kelas aktif: {{p.activeClass?.nama_kelas??'Belum diatur'}} · {{p.activeClass?.tahun_pelajaran?.tahun??''}}</p></div><section class="sneat-card mb-6 p-5 sm:p-6">
<h2 class="font-bold">Impor &amp; ekspor siswa</h2>
<p class="mt-2 text-sm text-slate-500">Gunakan template dengan kolom NIS, Nama, dan Kontak (opsional). Isi mulai baris 2; pertahankan format teks agar nol awal tidak hilang.</p>
<div class="mt-4 flex flex-wrap gap-3"><DownloadLink href="/master/siswa/template" class="rounded-lg border px-4 py-3 text-sm font-semibold">Unduh template XLSX</DownloadLink><DownloadLink v-if="p.activeClass" href="/master/siswa/export" class="rounded-lg border px-4 py-3 text-sm font-semibold">Ekspor siswa kelas aktif (.xlsx)</DownloadLink></div>
<p class="mt-3 text-xs text-slate-500">Ekspor memuat seluruh siswa kelas aktif (NIS, Nama, Kontak), tanpa mengikuti pencarian. Impor menambahkan siswa baru; NIS yang sudah ada dilewati.</p>
<form v-if="p.activeClass" @submit.prevent="importStudents" class="mt-5 space-y-3">
<label for="student-xlsx" class="block text-sm font-medium">File siswa (.xlsx), maksimal 2 MB / 1.000 siswa</label>
<input id="student-xlsx" ref="fileInput" type="file" accept=".xlsx" required :disabled="upload.processing" class="w-full min-w-0" :aria-invalid="!!upload.errors.file" aria-describedby="import-error" @change="upload.file=($event.target as HTMLInputElement).files?.[0]??null;upload.clearErrors()">
<p id="import-error" v-if="upload.errors.file" role="alert" class="text-sm text-rose-700">{{upload.errors.file}}</p>
<progress v-if="upload.progress" :value="upload.progress.percentage" max="100" class="w-full" aria-label="Progres impor"></progress>
<button :aria-busy="upload.processing" :disabled="upload.processing || !upload.file" class="sneat-primary rounded-lg px-4 py-3 text-sm font-semibold text-white disabled:opacity-50">{{upload.processing?'Mengimpor…':'Impor ke '+p.activeClass.nama_kelas}}</button>
</form><p v-else class="mt-4 text-sm text-amber-700">Atur kelas aktif di Pengaturan sebelum impor atau ekspor.</p>
</section><section class="sneat-card p-5 sm:p-6"><div class="flex items-center justify-between"><div><h2 class="font-bold">{{edit?'Edit siswa':'Tambah siswa'}}</h2><p class="mt-1 text-xs text-slate-500">Data otomatis masuk ke kelas aktif.</p></div><button v-if="edit" @click="reset" class="text-sm font-semibold text-indigo-600">Batal edit</button></div><div v-if="Object.keys(f.errors).length" role="alert" class="mt-3 text-sm text-rose-700"><p v-for="(error,key) in f.errors" :key="key">{{error}}</p></div><form @submit.prevent="save" class="mt-5 space-y-4"><div><label class="mb-2 block text-sm font-medium">NIS</label><input v-model="f.nis" class="w-full" placeholder="Masukkan NIS" required><p v-if="f.errors.nis" class="mt-1 text-xs text-rose-600">{{f.errors.nis}}</p></div><div><label class="mb-2 block text-sm font-medium">Nama lengkap</label><input v-model="f.nama" class="w-full" placeholder="Masukkan nama siswa" required></div><div><label class="mb-2 block text-sm font-medium">Kontak <span class="font-normal text-slate-400">(opsional)</span></label><input v-model="f.kontak" class="w-full" placeholder="Nomor kontak"></div><button :aria-busy="f.processing" :disabled="f.processing" class="sneat-primary w-full rounded-lg px-4 py-3 text-sm font-semibold text-white">{{f.processing?'Menyimpan…':edit?'Simpan perubahan':'Simpan siswa'}}</button></form></section><section class="sneat-card mt-6 overflow-hidden"><div class="border-b p-5"><h2 class="font-bold">Daftar siswa</h2><p class="mt-1 text-xs text-slate-500">{{p.items.length}} siswa pada kelas aktif</p></div><div class="p-5"><label for="search-students" class="block text-sm font-medium">Cari siswa</label><input id="search-students" v-model="search" type="search" placeholder="Nama atau NIS" class="mt-2 w-full"><p class="mt-2 text-xs">{{filtered.length}} dari {{p.items.length}} siswa</p></div><div class="overflow-x-auto"><table class="sneat-table w-full text-left text-sm"><thead class="text-xs uppercase"><tr><th class="p-4">NIS</th><th class="p-4">Nama</th><th class="p-4">Kontak</th><th class="p-4 text-right">Saldo tabungan</th><th class="p-4 text-right">Aksi</th></tr></thead><tbody class="divide-y"><tr v-for="x in filtered" :key="x.id"><td class="p-4">{{x.nis}}</td><td class="p-4 font-semibold"><Link :href="`/master/siswa/${x.id}/buku`" class="text-indigo-600 underline underline-offset-4">{{x.nama}}</Link></td><td class="p-4 text-slate-500">{{x.kontak||'—'}}</td><td class="p-4 text-right whitespace-nowrap font-semibold text-emerald-600">Rp {{rp(x.saldo_total)}}</td><td class="table-actions p-4 text-right"><Link :href="`/master/siswa/${x.id}/buku`" class="rounded bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-700">Buku tabungan</Link><button @click="load(x)" class="rounded bg-indigo-50 px-3 py-2 text-xs font-semibold text-indigo-600">Edit</button><button v-if="!x.transaksi_count" @click="remove(x.id)" class="rounded bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-600">Hapus</button></td></tr><tr v-if="!filtered.length"><td colspan="5" class="p-10 text-center text-slate-400">Tidak ada siswa yang cocok.</td></tr></tbody></table></div></section></div></main></MainLayout></template>
